"""Render the database schema as Markdown + Mermaid, from the SQLAlchemy models.

`make db-schema` writes it to docs/DB_SCHEMA.md; a test fails when that file is out of date.
"""

from pathlib import Path

from sqlalchemy import CheckConstraint, Column, Enum, ForeignKeyConstraint, Table, UniqueConstraint
from sqlalchemy.dialects import postgresql

import app.modules  # noqa: F401  (registers every model on Base.metadata)
from app.core.config import REPO_ROOT
from app.core.db import Base

OUTPUT = REPO_ROOT / "docs" / "DB_SCHEMA.md"

HEADER = """# Database schema

<!-- Generated by `make db-schema` from the SQLAlchemy models: do not edit by hand. -->

Every table also has `created_at` and `updated_at` (`timestamptz`, set by the database).
Shared reference data (tenders, forms, fields) is the same for every tenant; what a tenant
produces (`form_fill`, `answer`) carries its `tenant_id`, directly or through its fill.
"""

TIMESTAMPS = {"created_at", "updated_at"}
TYPE_NAMES = {"timestamp with time zone": "timestamptz"}


def render() -> str:
    tables = sorted(Base.metadata.tables.values(), key=lambda table: table.name)
    lines = [HEADER, "```mermaid", "erDiagram"]
    for table in tables:
        for fk in sorted(table.foreign_key_constraints, key=_fk_column):
            # A nullable foreign key: the child may have no parent.
            parent = "|o" if _column(fk).nullable else "||"
            lines.append(
                f"    {fk.referred_table.name} {parent}--o{{ {table.name} : {_fk_column(fk)}"
            )
    for table in tables:
        lines.append(f"    {table.name} {{")
        lines.extend(f"        {_attribute(table, column)}" for column in _columns(table))
        lines.append("    }")
    lines.append("```")
    lines.append("")
    lines.append("## Constraints and indexes")
    for table in tables:
        lines.append("")
        lines.append(f"### `{table.name}`")
        lines.append("")
        lines.extend(f"- {line}" for line in _constraints(table))
    return "\n".join(lines) + "\n"


def _columns(table: Table) -> list[Column]:
    return [column for column in table.columns if column.name not in TIMESTAMPS]


def _attribute(table: Table, column: Column) -> str:
    keys = []
    if column.primary_key:
        keys.append("PK")
    if column.foreign_keys:
        keys.append("FK")
    if any(_is_single_unique(c, column) for c in table.constraints):
        keys.append("UK")
    notes = []
    if isinstance(column.type, Enum):
        notes.append(" | ".join(column.type.enums))
    if column.nullable and not column.primary_key:
        notes.append("nullable")
    parts = [_type(column), column.name]
    if keys:
        parts.append(",".join(keys))
    if notes:
        parts.append(f'"{"; ".join(notes)}"')
    return " ".join(parts)


def _type(column: Column) -> str:
    if isinstance(column.type, Enum):
        return "text"
    name = column.type.compile(dialect=postgresql.dialect()).lower()
    return TYPE_NAMES.get(name, name).replace(" ", "_")


def _constraints(table: Table) -> list[str]:
    lines = []
    for fk in sorted(table.foreign_key_constraints, key=_fk_column):
        target = f"{fk.referred_table.name}.{fk.elements[0].column.name}"
        on_delete = f", on delete {fk.ondelete.lower()}" if fk.ondelete else ""
        lines.append(f"FK `{_fk_column(fk)}` → `{target}`{on_delete}")
    for constraint in sorted(table.constraints, key=lambda c: str(c.name)):
        if isinstance(constraint, UniqueConstraint):
            lines.append(f"unique `({', '.join(c.name for c in constraint.columns)})`")
        elif isinstance(constraint, CheckConstraint) and not _is_enum_check(table, constraint):
            lines.append(f"check `{constraint.sqltext}`")
    for index in sorted(table.indexes, key=lambda i: str(i.name)):
        kind = "unique index" if index.unique else "index"
        lines.append(f"{kind} `({', '.join(c.name for c in index.columns)})`")
    return lines or ["none besides the primary key"]


def _fk_column(fk: ForeignKeyConstraint) -> str:
    return _column(fk).name


def _column(fk: ForeignKeyConstraint) -> Column:
    return next(iter(fk.columns))


def _is_single_unique(constraint: object, column: Column) -> bool:
    return isinstance(constraint, UniqueConstraint) and list(constraint.columns) == [column]


def _is_enum_check(table: Table, constraint: CheckConstraint) -> bool:
    # Enum values are already shown on their column.
    return any(isinstance(c.type, Enum) for c in table.columns if c.name in str(constraint.sqltext))


def write(path: Path = OUTPUT) -> None:
    path.write_text(render(), encoding="utf-8")


if __name__ == "__main__":
    write()
    print(f"Wrote {OUTPUT.relative_to(REPO_ROOT)}")
